select  from external_manager_account a
left join external_manager_account p on p.id = a.parent_id and p.del_flag = '0'
where a.del_flag = '0'
and a.login_name like concat('%', #{loginName}, '%')
and a.woha_uid = #{wohaUid}
and a.role_code = #{roleCode}
and a.region_id = #{regionId}
and a.status = #{status}
and p.login_name like concat('%', #{parentLoginName}, '%')
and a.open_method = #{openMethod}
order by a.id desc

select  from external_manager_account a
left join external_manager_account p on p.id = a.parent_id and p.del_flag = '0'
where a.del_flag = '0' and a.id in
#{id}
and a.login_name like concat('%', #{loginName}, '%')
and a.role_code = #{roleCode}
and a.status = #{status}
order by a.id desc

