update external_manager_account

    real_name = #{realName}, woha_uid = #{wohaUid}, role_code = #{roleCode}, parent_id = #{parentId}, region_id = #{regionId}, permissions = #{permissions}, whatsapp = #{whatsapp}, remark = #{remark}, update_by = #{updateBy}
    , password = #{password}, pwd_update_date = #{pwdUpdateDate}

where id = #{id} and del_flag = '0'
